INSERT INTO social_and_env_grieviancemonitoringlog (case_no, sex, date_claim_recieved, name_of_person_receiving_complaint, how_complaint_was_received, name_of_complainant, tell_no, complaint_content, was_recieved_of_complaint_ack, expected_decision_date, was_decison_communicated_to_complainant, communication_method, was_complainant_satisfied_with_decision, brief_note_for_NO_answer, any_follow_up_action, date_created, decision_outcome_id, loginUser_id, project_id, type_of_investment_id) VALUES ('GR-TL167', 'M', '2023-06-18', 'Nuha Colley', 'In Person', 'Momodou Manneh', '2026892', 'During the GRC field visit, he verbally proposed D850,000.00 as fair compensation. In tensed discussion, he finally agreed land for land compensation.', 'Y', '2023-10-04', 'Y', 'In Person', 'Y', 'Not applicable', 'Open', '2025-04-28 17:03:11.4361130 ', 20009, 21, 'D309& D6530 -GM', 'GERMP T&D'), ('GR-TL168', 'M', '2023-06-18', 'Nuha Colley', 'Letter', 'Lamin Ceesay C/O Njundu Ceesay', '7245285', 'Mr Ceesay was proposed a compensation amount of 996,000.00for his plot of land measuring 20*20m which he rejected. He verbally claimed D1.7 million as a fair compensation on site during a field visit.', 'Y', '2023-10-03', 'Y', 'In Person', 'Y', 'Not applicable', 'Closed.', '2025-04-29 09:22:21.2896770 ', 20009, 21, 'D309& D6530 -GM', 'GERMP T&D'), ('GR-TL169', 'M', '2023-06-18', 'Nuha Colley', 'In Person', 'Fanta Janneh', '9097944/7642307', 'Mrs Janneh has a plot of land in Jambur measuring 20m x 30m which will be impacted by the T line. She rejected the RAP proposed of D360,000.00and agreed to land for land compensation', 'Y', '2023-10-03', 'Y', 'In Person', 'Y', 'Not applicable', 'Open', '2025-04-29 09:30:43.8499980 ', 20009, 21, 'D309& D6530 -GM', 'GERMP T&D'), ('GR-TL170', 'M', '2023-06-18', 'Nuha Colley', 'In Person', 'Abdou S Camara', '7410050', 'Mr Camara rejected the RAP disclosure for his plot of land measuring 30*247m at Jambur, He was called to write  and suggest an amount he considered